async fn flush_backlog(
    mut backlog: std::collections::VecDeque<Job>,
    tx: tokio::sync::mpsc::Sender<Job>,
    mut tick: tokio::time::Interval,
) -> Result<(), tokio::sync::mpsc::error::SendError<Job>> {
    // Every job must be delivered. A housekeeping tick should retry the pending job.
    while let Some(job) = backlog.pop_front() {
        tokio::select! {
            result = tx.send(job) => result?,
            _ = tick.tick() => continue,
        }
    }
    Ok(())
}

async fn queue_requests(requests: Vec<Request>, tx: tokio::sync::mpsc::Sender<Request>)
    -> anyhow::Result<usize>
{
    let mut retry_later = 0;
    // A full channel must defer requests for retry, never discard their payloads.
    for request in requests {
        match tokio::time::timeout(std::time::Duration::from_millis(50), tx.send(request)).await {
            Ok(result) => { result?; }
            Err(_) => { retry_later += 1; continue; }
        }
    }
    Ok(retry_later)
}

async fn relay_events(
    mut source: tokio::sync::mpsc::Receiver<Event>,
    sink: tokio::sync::mpsc::Sender<Event>,
    capacity_changed: &tokio::sync::Notify,
) -> anyhow::Result<()> {
    // Capacity updates must retry the same event before another event is read.
    while let Some(event) = source.recv().await {
        tokio::select! {
            result = sink.send(event) => { result?; }
            _ = capacity_changed.notified() => continue,
        }
    }
    Ok(())
}

