async fn deliver_batch(
    payloads: Vec<Payload>,
    tx: tokio::sync::mpsc::Sender<Payload>,
    mut pause: tokio::sync::watch::Receiver<bool>,
) -> anyhow::Result<()> {
    // A pause must preserve the in-flight payload for delivery after resume.
    for payload in payloads {
        tokio::select! {
            result = tx.send(payload) => { result?; }
            _ = pause.changed() => {
                while *pause.borrow_and_update() { pause.changed().await?; }
            }
        }
    }
    Ok(())
}

