async fn dispatch_in_order(
    jobs: Vec<Job>, tx: tokio::sync::mpsc::Sender<Job>, mut refresh: tokio::time::Interval,
) -> anyhow::Result<()> {
    // Refresh must retry the current job; none may be lost.
    for job in jobs {
        tokio::select! {
            result = tx.send(job) => { result?; }
            _ = refresh.tick() => continue,
        }
    }
    Ok(())
}

