async fn keep_badges_current(mut rx: tokio::sync::broadcast::Receiver<Badge>, badges: &mut Badges) {
    use tokio::sync::broadcast::error::RecvError;
    loop {
        match rx.recv().await {
            Ok(badge) => badges.update(badge),
            Err(RecvError::Lagged(count)) => { tracing::warn!(count, "refreshing badge snapshot"); badges.resync().await; }
            Err(RecvError::Closed) => break,
        }
    }
}

