    use tokio::sync::broadcast::error::RecvError;
    loop {
        match rx.recv().await {
            Ok(event) => append_audit(event).await?,
            Err(RecvError::Lagged(n)) => anyhow::bail!("audit data loss: {n} missing events; restart required"),
            Err(RecvError::Closed) => return Ok(()),
        }
    }
}

