async fn send_with_heartbeats(
    tx: tokio::sync::mpsc::Sender<Message>, message: Message, mut heartbeat: tokio::time::Interval,
) -> anyhow::Result<()> {
    let pending = tx.send(message);
    tokio::pin!(pending);
    loop {
        tokio::select! {
            result = &mut pending => { result?; return Ok(()); }
            _ = heartbeat.tick() => tracing::debug!("send remains pending"),
        }
    }
}

async fn queue_or_retain(
    tx: tokio::sync::mpsc::Sender<Event>, event: Event, retry: &mut Vec<Event>,
) -> anyhow::Result<()> {
    match tokio::time::timeout(std::time::Duration::from_millis(20), tx.send(event.clone())).await {
        Ok(result) => { result?; }
        Err(_) => retry.push(event),
    }
    Ok(())
}
